sys_script_include.script:
var CLMReviewDateHelper = Class.create();
CLMReviewDateHelper.prototype = {
    initialize: function() {},

    // salesOrg is read directly from customer_master1 — never derived from code prefix
    _getSalesOrg: function(customerCode) {
        var gr = new GlideRecord('x_birl3_clm_clm_customer_master1');
        if (gr.get('customer_code_sap', customerCode)) {
            return gr.getValue('salesorg');
        }
        return '';
    },

    fetchLiveDetails: function(customerCode) {
    var salesOrg = this._getSalesOrg(customerCode);
    if (!salesOrg) {
        gs.error('CLMReviewDateHelper: no salesorg found on customer_master1 for ' + customerCode);
        return null;
    }
    var wsdl = new CLM_NEW_WSDL1();
    var raw = wsdl.getCreditDetails(customerCode, salesOrg);
    if (!raw) return null;
    var parsed = JSON.parse(raw);

    var sd = parseFloat(parsed.activeSD);   // <-- use the real field name
    if (isNaN(sd)) sd = 0;

    return {
        creditLimit: parsed.creditLimit,
        currentReviewDate: parsed.followUpDate, // FollowUpDt
        activeSD: Math.abs(sd),
        customerName: parsed.customerName
    };
},
    type: 'CLMReviewDateHelper'
};
